CREATE OR REPLACE FUNCTION func_special_composite_presentation(data uuidtext) RETURNS TEXT AS $$ DECLARE conf_group TEXT; -- Змінна для групи (Довідники або Документи) conf_name TEXT; -- Змінна для назви об'єкта row_uid uuid; BEGIN conf_group := split_part(data.text, '.', 1); -- Отримаємо частину ДО крапки conf_name := split_part(data.text, '.', 2); -- Отримаємо частину ПІСЛЯ крапки row_uid := data.uuid;
IF conf_group = 'Довідники' THEN RETURN CASE conf_name WHEN 'Організації' THEN (SELECT "col_a1" FROM tab_a01 WHERE uid = row_uid) WHEN 'Номенклатура' THEN (SELECT "col_b1" FROM tab_a03 WHERE uid = row_uid) WHEN 'Виробники' THEN (SELECT "col_b6" FROM tab_a04 WHERE uid = row_uid) WHEN 'ВидиНоменклатури' THEN (SELECT "col_b8" FROM tab_a05 WHERE uid = row_uid) WHEN 'ПакуванняОдиниціВиміру' THEN (SELECT "col_c1" FROM tab_a06 WHERE uid = row_uid) WHEN 'Валюти' THEN (SELECT "col_c5" FROM tab_a07 WHERE uid = row_uid) WHEN 'Контрагенти' THEN (SELECT "col_c7" FROM tab_a08 WHERE uid = row_uid) WHEN 'Склади' THEN (SELECT "col_d9" FROM tab_a10 WHERE uid = row_uid) WHEN 'ВидиЦін' THEN (SELECT "col_e9" FROM tab_a12 WHERE uid = row_uid) WHEN 'ВидиЦінПостачальників' THEN (SELECT "col_f3" FROM tab_a13 WHERE uid = row_uid) WHEN 'Користувачі' THEN (SELECT "col_f6" FROM tab_a14 WHERE uid = row_uid) WHEN 'ФізичніОсоби' THEN (SELECT "col_g7" FROM tab_a16 WHERE uid = row_uid) WHEN 'СтруктураПідприємства' THEN (SELECT "col_h8" FROM tab_a18 WHERE uid = row_uid) WHEN 'КраїниСвіту' THEN (SELECT "col_i2" FROM tab_a19 WHERE uid = row_uid) WHEN 'Файли' THEN (SELECT "col_i5" FROM tab_a20 WHERE uid = row_uid) WHEN 'ХарактеристикиНоменклатури' THEN (SELECT "col_i7" FROM tab_a21 WHERE uid = row_uid) WHEN 'Номенклатура_Папки' THEN (SELECT "col_j1" FROM tab_a22 WHERE uid = row_uid) WHEN 'Контрагенти_Папки' THEN (SELECT "col_j4" FROM tab_a23 WHERE uid = row_uid) WHEN 'Склади_Папки' THEN (SELECT "col_j7" FROM tab_a24 WHERE uid = row_uid) WHEN 'Каси' THEN (SELECT "col_k8" FROM tab_a26 WHERE uid = row_uid) WHEN 'БанківськіРахункиОрганізацій' THEN (SELECT "col_l1" FROM tab_a27 WHERE uid = row_uid) WHEN 'ДоговориКонтрагентів' THEN (SELECT concat_ws (', ', "col_n4", "col_b8") FROM tab_a28 WHERE uid = row_uid) WHEN 'БанківськіРахункиКонтрагентів' THEN (SELECT "col_n7" FROM tab_a29 WHERE uid = row_uid) WHEN 'СтаттяРухуКоштів' THEN (SELECT "col_i7" FROM tab_a45 WHERE uid = row_uid) WHEN 'СеріїНоменклатури' THEN (SELECT "col_a3" FROM tab_b02 WHERE uid = row_uid) WHEN 'ПартіяТоварівКомпозит' THEN (SELECT "col_a1" FROM tab_b06 WHERE uid = row_uid) WHEN 'ВидиЗапасів' THEN (SELECT "col_a5" FROM tab_b13 WHERE uid = row_uid) WHEN 'Банки' THEN (SELECT "col_a2" FROM tab_a39 WHERE uid = row_uid) WHEN 'СкладськіПриміщення' THEN (SELECT "col_a2" FROM tab_a71 WHERE uid = row_uid) WHEN 'СкладськіКомірки' THEN (SELECT "col_a2" FROM tab_a72 WHERE uid = row_uid) WHEN 'ОбластьЗберігання' THEN (SELECT "col_a2" FROM tab_a73 WHERE uid = row_uid) WHEN 'ТипорозміриКомірок' THEN (SELECT "col_a2" FROM tab_a75 WHERE uid = row_uid) WHEN 'СкладськіКомірки_Папки' THEN (SELECT "col_j1" FROM tab_a76 WHERE uid = row_uid) WHEN 'Блокнот' THEN (SELECT "col_a2" FROM tab_a41 WHERE uid = row_uid) WHEN 'ЗбереженіЗвіти' THEN (SELECT "col_a2" FROM tab_b04 WHERE uid = row_uid) WHEN 'КасиККМ' THEN (SELECT "col_a2" FROM tab_b52 WHERE uid = row_uid) WHEN 'ПланРахунків' THEN (SELECT concat_ws (', ', "col_a1", "col_a2") FROM tab_b57 WHERE uid = row_uid) WHEN 'Категорії' THEN (SELECT "col_a2" FROM tab_b58 WHERE uid = row_uid) WHEN 'Статті' THEN (SELECT "col_a2" FROM tab_b59 WHERE uid = row_uid) WHEN 'ВидиПодатків' THEN (SELECT "col_a2" FROM tab_b60 WHERE uid = row_uid) WHEN 'ВидиЖурналів' THEN (SELECT "col_a2" FROM tab_b61 WHERE uid = row_uid) WHEN 'ОсновніЗасоби' THEN (SELECT "col_a2" FROM tab_b62 WHERE uid = row_uid) WHEN 'МалоцінніПредмети' THEN (SELECT "col_a2" FROM tab_b64 WHERE uid = row_uid) WHEN 'ГрошовіРахункиВласні' THEN (SELECT "col_a2" FROM tab_b65 WHERE uid = row_uid) WHEN 'НоменклатураВнутрішня' THEN (SELECT "col_a2" FROM tab_b66 WHERE uid = row_uid) WHEN 'НоменклатураВнутрішня_Папки' THEN (SELECT "col_a2" FROM tab_b67 WHERE uid = row_uid) WHEN 'Бланки' THEN (SELECT "col_a2" FROM tab_b68 WHERE uid = row_uid) WHEN 'Співробітники' THEN (SELECT "col_a2" FROM tab_b69 WHERE uid = row_uid) WHEN 'ТипиБухОперацій' THEN (SELECT "col_a2" FROM tab_b70 WHERE uid = row_uid) WHEN 'КласифікаторОдиницьВиміру' THEN (SELECT