END; ELSIF conf_group = 'Документи' THEN RETURN CASE conf_name WHEN 'ЗамовленняПостачальнику' THEN (SELECT "docname" FROM tab_a25 WHERE uid = row_uid) WHEN 'ПоступленняТоварівТаПослуг' THEN (SELECT "docname" FROM tab_a32 WHERE uid = row_uid) WHEN 'ЗамовленняКлієнта' THEN (SELECT "docname" FROM tab_a34 WHERE uid = row_uid) WHEN 'РеалізаціяТоварівТаПослуг' THEN (SELECT "docname" FROM tab_a36 WHERE uid = row_uid) WHEN 'ВстановленняЦінНоменклатури' THEN (SELECT "docname" FROM tab_a42 WHERE uid = row_uid) WHEN 'ПрихіднийКасовийОрдер' THEN (SELECT "docname" FROM tab_a44 WHERE uid = row_uid) WHEN 'РозхіднийКасовийОрдер' THEN (SELECT "docname" FROM tab_a48 WHERE uid = row_uid) WHEN 'ПереміщенняТоварів' THEN (SELECT "docname" FROM tab_a31 WHERE uid = row_uid) WHEN 'ПоверненняТоварівПостачальнику' THEN (SELECT "docname" FROM tab_a51 WHERE uid = row_uid) WHEN 'ПоверненняТоварівВідКлієнта' THEN (SELECT "docname" FROM tab_a53 WHERE uid = row_uid) WHEN 'АктВиконанихРобіт' THEN (SELECT "docname" FROM tab_a81 WHERE uid = row_uid) WHEN 'ВведенняЗалишків' THEN (SELECT "docname" FROM tab_a83 WHERE uid = row_uid) WHEN 'НадлишкиТоварів' THEN (SELECT "docname" FROM tab_a88 WHERE uid = row_uid) WHEN 'ПересортицяТоварів' THEN (SELECT "docname" FROM tab_a90 WHERE uid = row_uid) WHEN 'ПерерахунокТоварів' THEN (SELECT "docname" FROM tab_a92 WHERE uid = row_uid) WHEN 'ПсуванняТоварів' THEN (SELECT "docname" FROM tab_a94 WHERE uid = row_uid) WHEN 'ВнутрішнєСпоживанняТоварів' THEN (SELECT "docname" FROM tab_b07 WHERE uid = row_uid) WHEN 'РахунокФактура' THEN (SELECT "docname" FROM tab_b10 WHERE uid = row_uid) WHEN 'РозміщенняТоварівНаСкладі' THEN (SELECT "docname" FROM tab_a64 WHERE uid = row_uid) WHEN 'ПереміщенняТоварівНаСкладі' THEN (SELECT "docname" FROM tab_b09 WHERE uid = row_uid) WHEN 'ЗбіркаТоварівНаСкладі' THEN (SELECT "docname" FROM tab_b27 WHERE uid = row_uid) WHEN 'РозміщенняНоменклатуриПоКоміркам' THEN (SELECT "docname" FROM tab_b29 WHERE uid = row_uid) WHEN 'КорегуванняБоргу' THEN 