LECT "docname" FROM tab_c12 WHERE uid = row_uid) WHEN 'ПрийняттяДоОбліку' THEN (SELECT "docname" FROM tab_c13 WHERE uid = row_uid) WHEN 'ПоверненняПереданихТоварів' THEN (SELECT "docname" FROM tab_c14 WHERE uid = row_uid) WHEN 'РемонтОсновнихЗасобів' THEN (SELECT "docname" FROM tab_c15 WHERE uid = row_uid) WHEN 'РозподілІншихВитрат' THEN (SELECT "docname" FROM tab_c16 WHERE uid = row_uid) WHEN 'РозрахунокСобівартостіВипуску' THEN (SELECT "docname" FROM tab_c17 WHERE uid = row_uid) WHEN 'СписанняМатеріалів' THEN (SELECT "docname" FROM tab_c18 WHERE uid = row_uid) WHEN 'СписанняНезавершеногоВиробництва' THEN (SELECT "docname" FROM tab_c19 WHERE uid = row_uid) WHEN 'СписанняНематеріальнихАктивів' THEN (SELECT "docname" FROM tab_c20 WHERE uid = row_uid) WHEN 'СписанняОсновнихЗасобів' THEN (SELECT "docname" FROM tab_c21 WHERE uid = row_uid) WHEN 'СписанняВитратМайбутніхПеріодів' THEN (SELECT "docname" FROM tab_c22 WHERE uid = row_uid) WHEN 'СписанняТоварів' THEN (SELECT "docname" FROM tab_c23 WHERE uid = row_uid) WHEN 'Сторнування' THEN (SELECT "docname" FROM tab_c24 WHERE uid = row_uid)
